mapper.select:
SELECT 
FROM ledger_entry e
JOIN category c ON c.id = e.category_id
LEFT JOIN payment_method p ON p.id = e.payment_method_id
WHERE e.user_id = #{userId}
  AND e.entry_date BETWEEN #{from} AND #{to}
AND e.type = #{type}
AND e.category_id = #{categoryId}
AND e.payment_method_id = #{paymentMethodId}

  AND (e.title ILIKE #{keyword} ESCAPE '\' OR e.memo ILIKE #{keyword} ESCAPE '\')

ORDER BY e.entry_date DESC, e.id DESC

mapper.update:
UPDATE ledger_entry
SET entry_date = #{entryDate}, type = #{type}, category_id = #{categoryId}, title = #{title},
    amount = #{amount}, payment_method_id = #{paymentMethodId}, memo = #{memo}
WHERE id = #{id} AND user_id = #{userId}
